<script setup>
import { computed } from 'vue'
import { Check, Edit3, MessageCircle, MoreHorizontal, Send, ShieldAlert, X } from 'lucide-vue-next'
import { useStreamBotStore } from '../stores/streamBotStore'
const store = useStreamBotStore()
const highlight = (message) => /(?:нейро\s*зетка|зеточка|зетка|neyrozetka|!askbot)/i.test(message)
const queue = computed(() => store.queue)
</script>
<template>
  <section class="panel chat-panel"><div class="panel-head"><div><div class="panel-title"><span class="icon-purple"><MessageCircle :size="16" /></span>{{ $t('chat.title') }}<span class="live-chip small"><span class="status-dot"></span> {{ $t('common.live') }}</span></div><p>{{ $t('chat.subtitle') }}</p></div><button class="icon-button"><MoreHorizontal :size="18" /></button></div><div class="chat-toolbar"><label><input v-model="store.autoScroll" type="checkbox" /> {{ $t('chat.autoScroll') }}</label><div class="mode-switch"><button :class="{ selected: !store.preModeration }" @click="store.setRuntimeToggle('auto_reply', true)">{{ $t('chat.auto') }}</button><button :class="{ selected: store.preModeration }" @click="store.setRuntimeToggle('auto_reply', false)">{{ $t('chat.manual') }}</button></div></div><div class="chat-list"><div v-for="line in store.chat" :key="line.id" class="chat-line"><time>{{ line.time }}</time><span class="chat-badge" :class="line.badge.toLowerCase()">{{ line.badge || '•' }}</span><strong :style="{ color: line.color }">{{ line.user }}</strong><span :class="{ mention: highlight(line.message) }">{{ line.message }}</span></div></div><div class="queue-head"><div><span class="icon-amber"><ShieldAlert :size="15" /></span><b>{{ $t('chat.queue') }}</b><span class="queue-number">{{ queue.length }}</span></div><small>{{ store.preModeration ? $t('chat.manual') : $t('chat.auto') }}</small></div><div v-if="queue.length" v-for="item in queue" :key="item.id" class="queue-item"><div class="queue-meta"><span class="queue-user">{{ item.user }}</span><span>{{ item.time }}</span><b>{{ item.confidence }}% {{ $t('common.match') }}</b></div><p>{{ item.response }}</p><div class="queue-actions"><button class="approve" @click="store.approveQueue(item.id)"><Check :size="14" /> {{ $t('common.approve') }}</button><button @click="store.editQueue(item)"><Edit3 :size="14" /> {{ $t('common.edit') }}</button><button @click="store.rejectQueue(item.id)"><X :size="14" /> {{ $t('common.reject') }}</button><button class="send-jeet" @click="store.sendQueueToJeet(item.id)"><Send :size="13" /> {{ $t('chat.sendJeet') }}</button></div></div><div v-else class="empty-state">{{ $t('chat.empty') }}</div></section>
</template>
